import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_M": 32, "BLOCK_N": 32, "BLOCK_K": 32, "GROUP_SIZE_M": 1},
        ),
    ],
    key=["M", "N", "K"],
)
@triton.jit
def _gemm_bias_relu_kernel(
    a_ptr,
    b_t_ptr,
    bias_ptr,
    c_ptr,
    M,
    N,
    K,
    stride_am: tl.constexpr,
    stride_ak: tl.constexpr,
    stride_bk: tl.constexpr,
    stride_bn: tl.constexpr,
    stride_cm: tl.constexpr,
    stride_cn: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_SIZE_M: tl.constexpr,
):
    pid = tl.program_id(0)
    num_pid_m = tl.cdiv(M, BLOCK_M)
    num_pid_n = tl.cdiv(N, BLOCK_N)

    group_size = GROUP_SIZE_M * num_pid_n
    group_id = pid // group_size
    first_pid_m = group_id * GROUP_SIZE_M
    group_m = tl.minimum(num_pid_m - first_pid_m, GROUP_SIZE_M)

    pid_in_group = pid % group_size
    pid_m = first_pid_m + (pid_in_group % group_m)
    pid_n = pid_in_group // group_m

    a_desc = tl.make_tensor_descriptor(
        base=a_ptr,
        shape=(M, K),
        strides=(stride_am, stride_ak),
        block_shape=(BLOCK_M, BLOCK_K),
    )
    b_desc = tl.make_tensor_descriptor(
        base=b_t_ptr,
        shape=(K, N),
        strides=(stride_bk, stride_bn),
        block_shape=(BLOCK_K, BLOCK_N),
    )

    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
    for off_k in range(0, K, BLOCK_K):
        a = a_desc.load([pid_m * BLOCK_M, off_k])
        b = b_desc.load([off_k, pid_n * BLOCK_N])
        acc += tl.dot(a, b)

    offs_n = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)
    tl.max_contiguous(offs_n, BLOCK_N)
    bias = tl.load(bias_ptr + offs_n, mask=offs_n < N, other=0.0).to(tl.float32)

    out_dtype = c_ptr.type.element_ty
    acc = acc.to(out_dtype).to(tl.float32) + bias[None, :]
    acc = tl.maximum(acc, 0.0)

    c_desc = tl.make_tensor_descriptor(
        base=c_ptr,
        shape=(M, N),
        strides=(stride_cm, stride_cn),
        block_shape=(BLOCK_M, BLOCK_N),
    )
    c_desc.store([pid_m * BLOCK_M, pid_n * BLOCK_N], acc.to(out_dtype))


@triton.autotune(
    configs=[
        triton.Config(
            {
                "BLOCK_M": 32,
                "BLOCK_N": 32,
                "BLOCK_K": 32,
                "GROUP_SIZE_M": 1,
                "NUM_PROGS": 32,
            },
            num_warps=32,
            num_stages=3,
        ),
    ],
    key=["M", "N", "K"],
)
@triton.jit
def _gemm_bias_relu_persistent_kernel(
    a_ptr,
    b_t_ptr,
    bias_ptr,
    c_ptr,
    M,
    N,
    K,
    stride_am: tl.constexpr,
    stride_ak: tl.constexpr,
    stride_bk: tl.constexpr,
    stride_bn: tl.constexpr,
    stride_cm: tl.constexpr,
    stride_cn: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_SIZE_M: tl.constexpr,
    NUM_PROGS: tl.constexpr,
    grf_mode: tl.constexpr = "auto",
):
    pid = tl.program_id(0)
    num_pid_m = tl.cdiv(M, BLOCK_M)
    num_pid_n = tl.cdiv(N, BLOCK_N)
    num_tiles = num_pid_m * num_pid_n

    a_desc = tl.make_tensor_descriptor(
        base=a_ptr,
        shape=(M, K),
        strides=(stride_am, stride_ak),
        block_shape=(BLOCK_M, BLOCK_K),
    )
    b_desc = tl.make_tensor_descriptor(
        base=b_t_ptr,
        shape=(K, N),
        strides=(stride_bk, stride_bn),
        block_shape=(BLOCK_K, BLOCK_N),
    )
    c_desc = tl.make_tensor_descriptor(
        base=c_ptr,
        shape=(M, N),
        strides=(stride_cm, stride_cn),
        block_shape=(BLOCK_M, BLOCK_N),
    )

    tile_id = pid
    while tile_id < num_tiles:
        group_size = GROUP_SIZE_M * num_pid_n
        group_id = tile_id // group_size
        first_pid_m = group_id * GROUP_SIZE_M
        group_m = tl.minimum(num_pid_m - first_pid_m, GROUP_SIZE_M)

        pid_in_group = tile_id % group_size
        pid_m = first_pid_m + (pid_in_group % group_m)
        pid_n = pid_in_group // group_m

        acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
        for off_k in range(0, K, BLOCK_K):
            a = a_desc.load([pid_m * BLOCK_M, off_k])
            b = b_desc.load([off_k, pid_n * BLOCK_N])
            acc += tl.dot(a, b)

        offs_n = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)
        tl.max_contiguous(offs_n, BLOCK_N)
        bias = tl.load(bias_ptr + offs_n, mask=offs_n < N, other=0.0).to(tl.float32)

        out_dtype = c_ptr.type.element_ty
        acc = acc.to(out_dtype).to(tl.float32) + bias[None, :]
        acc = tl.maximum(acc, 0.0)

        c_desc.store([pid_m * BLOCK_M, pid_n * BLOCK_N], acc.to(out_dtype))

        tile_id += NUM_PROGS


def _get_num_workers(device=None):
    try:
        if device is not None and device.type == "xpu":
            if hasattr(torch, "xpu"):
                if hasattr(torch.xpu, "get_device_capability"):
                    cap = torch.xpu.get_device_capability()
                    if isinstance(cap, dict):
                        for key in (
                            "gpu_subslice_count",
                            "subslice_count",
                            "max_compute_units",
                            "gpu_eu_count",
                        ):
                            val = cap.get(key, None)
                            if isinstance(val, int) and val > 0:
                                return val
                if hasattr(torch.xpu, "get_device_properties"):
                    props = torch.xpu.get_device_properties(device.index or 0)
                    for key in (
                        "subslice_count",
                        "max_compute_units",
                        "multi_processor_count",
                    ):
                        if hasattr(props, key):
                            val = getattr(props, key)
                            if isinstance(val, int) and val > 0:
                                return val
        elif device is not None and device.type == "cuda":
            props = torch.cuda.get_device_properties(device)
            if (
                hasattr(props, "multi_processor_count")
                and props.multi_processor_count > 0
            ):
                return props.multi_processor_count
    except Exception:
        pass
    return 32


def _select_num_progs_cap(total_tiles: int, device=None):
    hw = _get_num_workers(device=device)
    cap = max(1, min(total_tiles, hw))
    if cap >= 256:
        return 256
    if cap >= 128:
        return 128
    if cap >= 64:
        return 64
    if cap >= 32:
        return 32
    return cap


def kernel_function(
    x: torch.Tensor,
    weight: torch.Tensor,
    bias: torch.Tensor,
    packed_weight_t: torch.Tensor = None,
):
    assert (
        isinstance(x, torch.Tensor)
        and isinstance(weight, torch.Tensor)
        and isinstance(bias, torch.Tensor)
    )
    assert x.ndim == 2 and weight.ndim == 2 and bias.ndim == 1
    assert x.shape[1] == weight.shape[1], "Incompatible shapes"
    assert bias.numel() == weight.shape[0], "Bias length mismatch"

    _supported_dtypes = (torch.float16, torch.bfloat16)
    target_dtype = x.dtype if x.dtype in _supported_dtypes else torch.bfloat16

    x_ready = (
        x
        if (x.dtype == target_dtype and x.is_contiguous())
        else x.to(dtype=target_dtype).contiguous()
    )
    weight_ready = (
        weight
        if (weight.dtype == target_dtype and weight.is_contiguous())
        else weight.to(dtype=target_dtype).contiguous()
    )
    bias_ready = (
        bias
        if (bias.dtype == target_dtype and bias.is_contiguous())
        else bias.to(dtype=target_dtype).contiguous()
    )

    if packed_weight_t is not None:
        weight_t_ready = (
            packed_weight_t
            if (
                packed_weight_t.dtype == target_dtype
                and packed_weight_t.is_contiguous()
            )
            else packed_weight_t.to(dtype=target_dtype).contiguous()
        )
    else:
        weight_t_ready = weight_ready.transpose(0, 1).contiguous()

    M, K = x_ready.shape
    N = weight_ready.shape[0]

    out = torch.empty((M, N), device=x.device, dtype=target_dtype)

    stride_am, stride_ak = x_ready.stride()
    stride_bk, stride_bn = weight_t_ready.stride()
    stride_cm, stride_cn = out.stride()

    total_tiles = triton.cdiv(M, 256) * triton.cdiv(N, 256)
    num_progs_cap = _select_num_progs_cap(total_tiles, device=x.device)

    # Use persistent scheduling when there are enough tiles to amortize looping.
    # Fall back to original kernel for very small grids to avoid persistent overhead.
    if total_tiles >= 8 and num_progs_cap >= 1:
        grid = lambda meta: (min(meta["NUM_PROGS"], num_progs_cap),)
        _gemm_bias_relu_persistent_kernel[grid](
            x_ready,
            weight_t_ready,
            bias_ready,
            out,
            M,
            N,
            K,
            stride_am,
            stride_ak,
            stride_bk,
            stride_bn,
            stride_cm,
            stride_cn,
        )
    else:
        grid = lambda meta: (
            triton.cdiv(M, meta["BLOCK_M"]) * triton.cdiv(N, meta["BLOCK_N"]),
        )
        _gemm_bias_relu_kernel[grid](
            x_ready,
            weight_t_ready,
            bias_ready,
            out,
            M,
            N,
            K,
            stride_am,
            stride_ak,
            stride_bk,
            stride_bn,
            stride_cm,
            stride_cn,
        )
    return out


batch_size = 1024
in_features = 8192
out_features = 8192
bias_shape = (out_features,)


def get_inputs():
    return [torch.rand(batch_size, in_features)]


def get_init_inputs():
    return [in_features, out_features, bias_shape]


@triton.autotune(
    configs=[
        triton.Config({"BLOCK_SIZE": 256}, num_warps=4, num_stages=2),
        triton.Config({"BLOCK_SIZE": 512}, num_warps=8, num_stages=2),
        triton.Config({"BLOCK_SIZE": 1024}, num_warps=16, num_stages=2),
        triton.Config({"BLOCK_SIZE": 2048}, num_warps=32, num_stages=2),
    ],
    key=["n_elements"],
)
@triton.jit
def _bias_relu_kernel(
    x_ptr,
    bias_ptr,
    out_ptr,
    n_elements,
    N,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements

    x_val = tl.load(x_ptr + offsets, mask=mask, other=0.0)
    bias_idx = offsets % N
    b_val = tl.load(bias_ptr + bias_idx, mask=mask, other=0.0)

    y = x_val + b_val
    y = tl.maximum(y.to(tl.float32), 0.0)
    out_dtype = out_ptr.dtype.element_ty
    tl.store(out_ptr + offsets, y.to(out_dtype), mask=mask)


class Model(nn.Module):
    def __init__(self, in_features, out_features, bias_shape):
        super().__init__()
        self.gemm = nn.Linear(in_features, out_features, bias=False)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self._weight_kn = None

    def forward(self, x):
        if self._weight_kn is None:
            w = self.gemm.weight.data.to(dtype=x.dtype).contiguous()
            self.gemm.weight.data = w
            self.bias.data = self.bias.data.to(dtype=x.dtype).contiguous()
            self._weight_kn = w.t().contiguous()
        return kernel_function(
            x.contiguous(), self.gemm.weight, self.bias, packed_weight_t=self._weight_kn
        )
